import { BrowserRouter as Router, Route, Routes, Navigate } from "react-router-dom";
import { allAdminRoutes, allBlankRoutes } from "./index.tsx";
import RequireUser from "../layout/RequireUser.tsx";
import { useSelector } from "react-redux";
import type { RootState } from "../../app/store.ts";
import usePermission from "../../shared/hooks/usePermission.ts";
import NotAuthorized from "../../features/exceptions/pages/NotAuthorized.tsx";

// Generated by Scripts/layout-setup.
import AuthLayout from "../layout/AuthLayout.tsx";

const Layout = AuthLayout;

const AllRoutes = () => {
  const isLoggedIn = useSelector((state: RootState) => state.auth.isLoggedIn);
  const { can, canAny } = usePermission();

  return (
    <Router>
      <Routes>
        <Route>
          {allBlankRoutes.map((route, index) => (
            <Route key={index} path={route.path} element={route.element} />
          ))}
        </Route>

        <Route>
          {allAdminRoutes.map((route, idx) => {
            if (!isLoggedIn) {
              return (
                <Route
                  key={idx}
                  path={route.path}
                  element={<Navigate to={`/?next=${route.path}`} replace />}
                />
              );
            }

            return (
              <Route key={idx} element={<RequireUser />}>
                <Route
                  path={route.path}
                  element={<Layout>{can(route.permission) && canAny(route.anyPermission ?? []) ? route.element : <NotAuthorized />}</Layout>}
                />
              </Route>
            );
          })}
        </Route>
      </Routes>
    </Router>
  );
};

export default AllRoutes;
